      $ZodType.init(this, def);
      this._zod.optin = "optional";
      util.defineLazy(this._zod, "values", () => def.innerType._zod.values);
      this._zod.parse = (payload:any, ctx:any) => {
        if (payload.value === undefined) {
          payload.value = typeof def.defaultValue === "function" ? def.defaultValue() : def.defaultValue;
          return payload;
        }
        const result = def.innerType._zod.run(payload, ctx);
        if (result instanceof Promise) {
          return result.then((r:any) => handleDefaultResult(r, def));
        }
        return handleDefaultResult(result, def);
      };
    }
  }

  return { $ZodDefault: $ZodDefaultClass };
});
